      }

      // printf("%d: %d %d\n", cur, ok, b[0]);
      if (!ok)
        continue;

      ++ans;
      for (int i = 0; i < N; ++i) {
        b[i] = tb[i] + 1;
      }
    }

    printf("Case #%d: %d\n", tt, ans);
  }
  return 0;
}
