#pragma comment(linker, "/STACK:100000000000")
typedef long long ll;
typedef unsigned long long ull;
typedef long double lld;
typedef pair<int, int> PII;
typedef pair<ll, ll> PLL;
typedef vector<int> VI;
typedef vector<string> VS;
typedef vector<double> VD;

vector<PII> horse;
vector<int> dis;
double memo[110][110];
double f(int ind, int curHorse) {
  ll sum = 0;
  for (int(i) = (curHorse); (i) < (ind); (i)++)
    sum += dis[i];
  if (sum > horse[curHorse].first)
    return 1e100;

  if (ind == dis.size())
    return 0;

  double res = 1e100;
  double &ret = memo[ind][curHorse];
  if (ret < 0)
    return ret;

  res = min(res,
            (double)dis[ind] / horse[curHorse].second + f(ind + 1, curHorse));
  res = min(res, (double)dis[ind] / horse[ind].second + f(ind + 1, ind));

  return ret = res;
}
int main() {
  freopen("a.in", "r", stdin);
  freopen("a.out", "w", stdout);
  int Tcas;
  cin >> Tcas;
  for (int(cas) = 0; (cas) < (Tcas); (cas)++) {
    printf("Case #%d: ", cas + 1);
    int n, q;
    cin >> n >> q;
    horse.clear();
    dis.clear();
    memset((memo), (-1), sizeof(memo));
    for (int(i) = 0; (i) < (n); (i)++) {
      PII p;
      cin >> p.first >> p.second;
      horse.push_back(p);
    }
    for (int(i) = 0; (i) < (n); (i)++)
      for (int(j) = 0; (j) < (n); (j)++) {
        int k;
        cin >> k;
        if (i + 1 == j)
          dis.push_back(k);
      }
    for (int(qq) = 0; (qq) < (q); (qq)++) {
      int st, en;
      cin >> st >> en;
      cout << fixed << setprecision(9) << f(0, 0) << " ";
    }
    cout << endl;
  }
}
